public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[][] result = new int[n][n];
    int[] xDir = {0, 1, 0, -1}; // R, D, L, U
    int[] yDir = {1, 0, -1, 0}; // R, D, L, U

    int centerX = n / 2;
    int centerY = n / 2;
    result[centerX][centerY] = -1; // Mark center for Takahashi

    int x = centerX;
    int y = centerY + 1;
    int tmpDir = 0;
    int tmp = 1;

    while (tmp <= n * n - 1) {
        if (x >= 0 && x < n && y >= 0 && y < n && result[x][y] == 0) {
            result[x][y] = tmp;
            tmp++;
        } else {
            x -= xDir[tmpDir];
            y -= yDir[tmpDir];
            tmpDir = (tmpDir + 1) % 4;
        }
        x += xDir[tmpDir];
        y += yDir[tmpDir];
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (result[i][j] == -1) {
                System.out.print("T ");
            } else {
                System.out.print(result[i][j] + " ");
            }
        }
        System.out.println();
    }
}
